#!/usr/bin/env python3
"""Internal HAL layout: one schema for C, NASM offsets and Rust CPU capacity."""

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def outputs():
    schema = json.loads((ROOT / "hal/src/cpu_local.json").read_text())
    fields = schema["fields"]
    capacity = schema["capacity"]
    if len(set(fields)) != len(fields) or not 1 <= capacity <= 256:
        raise ValueError("invalid CPU layout")
    c = [
        "/* Generated by tools/gen_cpu_local.py. */",
        "#ifndef DUNIT_CPU_LOCAL_H",
        "#define DUNIT_CPU_LOCAL_H",
        "#include <stdint.h>",
        "#include <stddef.h>",
        f"#define HAL_CPU_CAPACITY {capacity}",
        "typedef struct {",
    ]
    c += [f"    uint64_t {name};" for name in fields]
    c += [
        "} __attribute__((aligned(64))) hal_cpu_local_t;",
        f'_Static_assert(sizeof(hal_cpu_local_t)=={((len(fields)*8+63)//64)*64},"CPU stride");',
    ]
    c += [
        f'_Static_assert(offsetof(hal_cpu_local_t,{name})=={i*8},"CPU {name}");'
        for i, name in enumerate(fields)
    ]
    c += [
        "void hal_cpu_local_init(uint64_t index);",
        "uint64_t hal_cpu_index(void);",
        "#endif",
        "",
    ]
    asm = (
        ["; Generated by tools/gen_cpu_local.py."]
        + [f"%define CPU_{name.upper()} {i*8}" for i, name in enumerate(fields)]
        + [""]
    )
    rust = [
        "// Generated by tools/gen_cpu_local.py.",
        f"pub const CPU_CAPACITY:usize={capacity};",
        "",
    ]
    return [
        (ROOT / "hal/src/cpu_local.h", "\n".join(c)),
        (ROOT / "hal/src/cpu_local.inc", "\n".join(asm)),
        (ROOT / "kernel/src/cpu_layout.rs", "\n".join(rust)),
    ]


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--check", action="store_true")
    a = p.parse_args()
    for path, text in outputs():
        if a.check:
            if not path.exists() or path.read_text() != text:
                raise SystemExit(f"stale {path}")
        else:
            path.write_text(text)


if __name__ == "__main__":
    main()
